package dev.zomboid.firstaid;
import java.util.*;
public class Checks {static int tests;static void check(boolean b){tests++;if(!b)throw new AssertionError(tests);}public static class Part {public float currentHealth;public Part(float n){currentHealth=n;}public int getMaxHealth(){return 4;}}public static class Model extends ArrayList<Part> {public boolean criticalConditionActive;}public static class Player {public boolean isAlive(){return true;}public float getMaxHealth(){return 20;}}
 public static void main(String[] args){float[] all={4,4,4,4,4,4,4,4},max=all.clone();check(Rules.health(all,max,20)==20);for(int i=0;i<8;i++){float[] h=all.clone();h[i]=0;check(Rules.health(h,max,20)>0);int mask=Rules.mask(0,h);check(mask==(1<<i));h[i]=.5f;check(Rules.mask(mask,h)==mask);h[i]=1;check(Rules.mask(mask,h)==0);}float[] h=all.clone();h[0]=h[4]=0;check(Rules.health(h,max,20)==15);check(Rules.health(new float[8],max,20)==0);check(Rules.mask(0,new float[]{.5f})==0);check(Rules.speed(255)==-.70);check(Rules.damage(255)==-.5);check(Rules.attackSpeed(255)==-.5);check(Rules.speed(0)==0&&Rules.damage(0)==0&&Rules.attackSpeed(0)==0);Model model=new Model();for(float n:h)model.add(new Part(n));check(!ZeroParts.dead(model,new Player()));check(ZeroParts.health(model,new Player())==15);for(Part p:model)p.currentHealth=0;check(ZeroParts.dead(model,new Player()));check(Revival.chance(0)==.25);check(Math.abs(Revival.chance(10)-.45)<.00001);check(Revival.chance(20)==Revival.chance(10));model.criticalConditionActive=true;check(!ZeroParts.dead(model,new Player())&&ZeroParts.health(model,new Player())==1);System.out.println(tests+" simulated health/zero-part cases passed");}}
